char * cJSON_PrintTm(const struct Tm * x) {
    char * s = NULL;
    if (NULL != x) {
        cJSON * j = cJSON_CreateTm(x);
        if (NULL != j) {
            s = cJSON_Print(j);
            cJSON_Delete(j);
        }
    }
    return s;
}

void cJSON_DeleteTm(struct Tm * x) {
    if (NULL != x) {
        if (NULL != x->code) {
            cJSON_free(x->code);
        }
        if (NULL != x->code_international) {
            cJSON_free(x->code_international);
        }
        if (NULL != x->lds) {
            cJSON_DeleteLds(x->lds);
        }
        if (NULL != x->logo) {
            cJSON_free(x->logo);
        }
        if (NULL != x->name) {
            cJSON_free(x->name);
        }
        if (NULL != x->name_international) {
            cJSON_free(x->name_international);
        }
        if (NULL != x->pl) {
            char **keys1 = NULL;
            size_t count1 = hashtable_get_keys(x->pl, &keys1);
            if (NULL != keys1) {
                for (size_t index1 = 0; index1 < count1; index1++) {
                    struct Pl *x1 = hashtable_lookup(x->pl, keys1[index1]);
                    if (NULL != x1) {
                        cJSON_DeletePl(x1);
                    }
                }
                cJSON_free(keys1);
            }
            hashtable_release(x->pl);
        }
        if (NULL != x->scoring) {
            struct Scorer * x1 = list_get_head(x->scoring);
            while (NULL != x1) {
                cJSON_DeleteScorer(x1);
                x1 = list_get_next(x->scoring);
            }
            list_release(x->scoring);
        }
        if (NULL != x->short_name) {
            cJSON_free(x->short_name);
        }
        if (NULL != x->short_name_international) {
            cJSON_free(x->short_name_international);
        }
        if (NULL != x->shot) {
            struct Shot * x1 = list_get_head(x->shot);
            while (NULL != x1) {
                cJSON_DeleteShot(x1);
                x1 = list_get_next(x->shot);
            }
            list_release(x->shot);
        }
        cJSON_free(x);
    }
}
